        await client.patch(
            "/api/admin/settings", json={"deploy_repo_identity": "acme/widget"}
        )
        resp = await client.get("/api/admin/settings")
        assert resp.status_code == 200
        data = resp.json()
        assert data["deploy_identity_resolved"] == "acme/widget"

