    @pytest.mark.asyncio
    async def test_spawn_task_links_debt(self, client: AsyncClient, db_session):
        """spawn_task with debt_id stamps detail.linked_tasks and echoes
        linked_debt_id."""
        from app.models import CompletionDebtEntry

